function tarjan(graph) {
  const index = new Map();      // discovery order
  const low = new Map();        // lowest index reachable, see above
  const onStack = new Set();
  const stack = [];
  const components = [];
  let counter = 0;

  function visit(v) {
    index.set(v, counter);
    low.set(v, counter);
    counter++;
    stack.push(v);
    onStack.add(v);

    for (const w of graph.neighbors(v)) {
      if (!index.has(w)) {
        visit(w);                                   // tree edge
        low.set(v, Math.min(low.get(v), low.get(w)));
      } else if (onStack.has(w)) {
        // w is an ancestor or a sibling still being processed, so it can
        // reach back to v. Use its INDEX, not its low.
        low.set(v, Math.min(low.get(v), index.get(w)));
      }
      // w visited but off the stack: it is in a finished component that
      // cannot reach us. Ignore it entirely.
    }

    if (low.get(v) === index.get(v)) {              // v is a root
      const component = [];
      let w;
      do {
        w = stack.pop();
        onStack.delete(w);
        component.push(w);
      } while (w !== v);
      components.push(component);
    }
  }

  for (const v of graph.nodes) if (!index.has(v)) visit(v);
  return components;
}

function kosaraju(graph) {
  const visited = new Set();
  const finishOrder = [];

  function dfs(v) {
    visited.add(v);
    for (const w of graph.neighbors(v)) {
      if (!visited.has(w)) dfs(w);
    }
    finishOrder.push(v);          // record on the way out, not the way in
  }
  for (const v of graph.nodes) if (!visited.has(v)) dfs(v);

  // Build the transpose: every edge flipped.
  const reverse = new Map(graph.nodes.map((v) => [v, []]));
  for (const v of graph.nodes) {
    for (const w of graph.neighbors(v)) reverse.get(w).push(v);
  }

  visited.clear();
  const components = [];

  function collect(v, component) {
    visited.add(v);
    component.push(v);
    for (const w of reverse.get(v)) {
      if (!visited.has(w)) collect(w, component);
    }
  }

  while (finishOrder.length > 0) {
    const v = finishOrder.pop();    // latest finisher first
    if (!visited.has(v)) {
      const component = [];
      collect(v, component);
      components.push(component);
    }
  }
  return components;
}

